from collections import deque


def classify_root(N, edges, s, T):
    edges = list(edges)
    reverse = [[] for _ in range(N)]
    for u, v, w in edges:
        reverse[v].append(u)

    # Identify vertices from which T is reachable.
    reaches_T = [False] * N
    reaches_T[T] = True
    queue = deque([T])
    while queue:
        v = queue.popleft()
        for u in reverse[v]:
            if not reaches_T[u]:
                reaches_T[u] = True
                queue.append(u)

    if not reaches_T[s]:
        return ("unreachable", None)

    relevant_edges = [
        (u, v, w) for u, v, w in edges
        if reaches_T[u] and reaches_T[v]
    ]

    dist = [None] * N
    dist[s] = 0

    # Synchronous Bellman-Ford: each round uses only the previous round.
    for _ in range(N - 1):
        next_dist = dist.copy()
        changed = False
        for u, v, w in relevant_edges:
            if dist[u] is None:
                continue
            candidate = dist[u] + w
            if next_dist[v] is None or candidate < next_dist[v]:
                next_dist[v] = candidate
                changed = True
        dist = next_dist
        if not changed:
            return ("finite", dist[T])

